/**
 * Match-object contract test: asserts that the router generated by markopack's
 * vendored codegen produces match objects compatible with the *installed*
 * @marko/run runtime.
 *
 * This guards against upstream runtime drift like the 0.11 change where
 * `createContext` started reading `route.options.params` — a breakage that
 * compiled fine and only crashed at request time.
 *
 * Usage:
 *   node scripts/test-match-contract.mjs
 */

import { execFileSync } from "node:child_process";
import { createRequire } from "node:module";
import { pathToFileURL } from "node:url";
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(new URL("..", import.meta.url).pathname);
const exampleDir = path.join(root, "examples/rspack-basic");
const serverBundle = path.join(exampleDir, "dist/server/index.cjs");

// Resolve the runtime the same way the rspack config does: through the
// installed @marko/run package, bypassing its exports map with a file URL
// (deep import of dist/runtime/internal.js).
const projectRequire = createRequire(path.join(root, "package.json"));
const runRoot = projectRequire
  .resolve("@marko/run")
  .replace(/(src|dist)[\\/]runtime[\\/].*$/, "");
const runtimeInternal = path.join(runRoot, "dist/runtime/internal.js");

if (!fs.existsSync(runtimeInternal)) {
  console.error(`Cannot find @marko/run runtime at ${runtimeInternal}`);
  process.exit(1);
}

console.log("Building example (rspack-basic)...");
execFileSync("npm", ["run", "build"], {
  cwd: exampleDir,
  stdio: ["ignore", "ignore", "inherit"],
  shell: true,
});

if (!fs.existsSync(serverBundle)) {
  console.error(`Server bundle not found at ${serverBundle}`);
  process.exit(1);
}

// Requiring the routed server bundle populates globalThis.__marko_run__.
// It is CJS, so use createRequire — a dynamic import() would leave the
// global unset if the bundle's side effects land in a different realm.
projectRequire(serverBundle);
const run = globalThis.__marko_run__;
if (typeof run?.match !== "function") {
  console.error("Server bundle did not expose __marko_run__.match()");
  process.exit(1);
}

// --- Part 1: match() shape contract ---------------------------------------
// Every field the runtime reads off a match object must be present and
// well-typed: handler, params, meta, path, options.

const CASES = [
  { method: "GET", pathname: "/", path: "/", params: {} },
  { method: "GET", pathname: "/blog/hello-world", path: "/blog/$slug", params: { slug: "hello-world" } },
  { method: "GET", pathname: "/products/books/42", path: "/products/$category/$id", params: { category: "books", id: "42" } },
  { method: "GET", pathname: "/docs/setup/install", path: "/docs/$$rest", params: { rest: "setup/install" } },
  { method: "GET", pathname: "/api/users", path: "/api/users", params: {} },
  { method: "POST", pathname: "/", path: "/", params: {} },
];

// Non-matching requests must return a falsy value, never a malformed object.
const NON_MATCHES = [
  { method: "GET", pathname: "/nonexistent" },
  { method: "DELETE", pathname: "/" },
  { method: "GET", pathname: "/blog/" },
];

let passed = 0;
let failed = 0;

function check(label, ok, detail) {
  if (ok) {
    passed++;
  } else {
    failed++;
    console.log(`  FAIL ${label}${detail ? `: ${detail}` : ""}`);
  }
}

console.log("\nMatch shape contract:");
for (const c of CASES) {
  const label = `${c.method} ${c.pathname}`;
  let match;
  try {
    match = run.match(c.method, c.pathname);
  } catch (err) {
    check(label, false, `match() threw: ${err.message}`);
    continue;
  }

  check(`${label} matched`, match != null, `got ${JSON.stringify(match)}`);
  if (!match) continue;

  check(
    `${label} handler is a function`,
    typeof match.handler === "function",
    `typeof ${typeof match.handler}`,
  );
  check(
    `${label} params`,
    JSON.stringify(match.params) === JSON.stringify(c.params),
    `got ${JSON.stringify(match.params)}, expected ${JSON.stringify(c.params)}`,
  );
  check(
    `${label} meta is an object`,
    match.meta != null && typeof match.meta === "object" && !Array.isArray(match.meta),
    `got ${JSON.stringify(match.meta)}`,
  );
  check(
    `${label} path is the route pattern`,
    match.path === c.path,
    `got ${JSON.stringify(match.path)}, expected ${JSON.stringify(c.path)}`,
  );
  check(
    `${label} options is an object`,
    match.options != null && typeof match.options === "object" && !Array.isArray(match.options),
    `got ${JSON.stringify(match.options)} — this field broke in @marko/run 0.11`,
  );
}

for (const c of NON_MATCHES) {
  const label = `${c.method} ${c.pathname} does not match`;
  let match;
  try {
    match = run.match(c.method, c.pathname);
  } catch (err) {
    check(label, false, `match() threw: ${err.message}`);
    continue;
  }
  check(label, !match, `got ${JSON.stringify({ ...match, handler: typeof match?.handler })}`);
}

// --- Part 2: real-runtime handshake ----------------------------------------
// Feed generated matches to the installed runtime's createContext — the
// function whose field accesses define the actual contract.

console.log("\nRuntime handshake (createContext from installed @marko/run):");
const { createContext } = await import(pathToFileURL(runtimeInternal).href);
const { version: runVersion } = JSON.parse(
  fs.readFileSync(path.join(runRoot, "package.json"), "utf8"),
);

for (const c of CASES.slice(0, 4)) {
  const label = `${c.method} ${c.pathname}`;
  const match = run.match(c.method, c.pathname);
  const request = new Request(`http://localhost${c.pathname}`, { method: c.method });
  try {
    const context = createContext(match, request, { request });
    // Reading .params walks the route.options.params getter path that
    // crashed before markopack emitted `options: {}`.
    const paramsOk =
      JSON.stringify(context.params) === JSON.stringify(c.params);
    check(
      `${label} createContext + context.params`,
      paramsOk,
      `got ${JSON.stringify(context.params)}, expected ${JSON.stringify(c.params)}`,
    );
    check(`${label} context.route`, context.route === c.path, `got ${JSON.stringify(context.route)}`);
    check(`${label} context.method`, context.method === c.method.toUpperCase(), `got ${JSON.stringify(context.method)}`);
  } catch (err) {
    check(`${label} createContext`, false, `threw: ${err.message}`);
  }
}

console.log(`\n  ${passed} passed, ${failed} failed (@marko/run ${runVersion})`);
process.exit(failed > 0 ? 1 : 0);
